import ast,hashlib,json,pathlib,subprocess
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
p=json.loads(pathlib.Path('proposal.json').read_text())
def validate(x,s,path='"'$'"'):
 t=s.get('type')
 checks={'object':lambda:isinstance(x,dict),'array':lambda:isinstance(x,list),'string':lambda:isinstance(x,str),'boolean':lambda:isinstance(x,bool)}
 if t: assert checks[t](),(path,t,type(x))
 if 'enum' in s: assert x in s['enum'],path
 if 'const' in s: assert x==s['const'],path
 if isinstance(x,str): assert len(x)>=s.get('minLength',0),path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x): validate(v,s.get('items',{}),path+'['+str(i)+']')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=x.keys(),(path,'required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False: assert set(x)<=set(props),(path,'extra keys')
  for k,v in x.items():
   if k in props: validate(v,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert r['context']['previous_runtime_error'] is None
original=ast.parse(pathlib.Path('history_r0013_required_rank.py').read_text())
old_model=next(n for n in original.body if isinstance(n,ast.ClassDef) and n.name=='Model')
old_methods={n.name:n for n in old_model.body if isinstance(n,ast.FunctionDef)}
all_trees=[]
allowed_imports={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
for v in p['variants']:
 file=v['file']; source=pathlib.Path(file).read_text(); tree=ast.parse(source); compile(tree,file,'exec')
 assert pathlib.Path(file).name==file and file.endswith('.py')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert cfg==v['config']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed_imports for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed_imports
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__','compile','input'}
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in model.body if isinstance(n,ast.FunctionDef)}
 preserved=[]
 for k,node in old_methods.items():
  if k not in ('__init__','forward','diagnostics'):
   assert ast.dump(node)==ast.dump(methods[k]),k
   preserved.append(k)
 assert all(ast.dump(a)==ast.dump(b) for a,b in zip(old_methods['__init__'].body,methods['__init__'].body))
 assert len(methods['__init__'].body)==len(old_methods['__init__'].body)+5
 extra_init=methods['__init__'].body[len(old_methods['__init__'].body):]
 assert not any(isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id in ('nn','torch') for x in extra_init for n in ast.walk(x))
 for node in tree.body:
  if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in node.targets): node.value=ast.Constant(value='CONFIG_NORMALIZED')
 all_trees.append(ast.dump(tree))
 print(file,'syntax/config/import/API boundaries OK; unchanged inherited methods',len(preserved),'sha256',hashlib.sha256(source.encode()).hexdigest())
assert len(set(all_trees))==1
assert len(set(v['name'] for v in p['variants']))==4
assert len(set(v['file'] for v in p['variants']))==4
assert {(v['config']['comparison_aggregation'],v['config']['comparison_metric']) for v in p['variants']}=={('all','rank'),('all','decay'),('latest','rank'),('latest','decay')}
assert hashlib.sha256(pathlib.Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
assert hashlib.sha256(pathlib.Path('history_r0013_required_rank.py').read_bytes()).hexdigest()=='5b4a04b15d711699b21b3b8d35db19104f445b211adf394ee287d9c45b47c2b3'
print('Complete exposed study schema passed; four model ASTs identical except CONFIG; ancestor constructor is exact prefix plus five nonrandom selector/guard statements.')
print('Diagnostics: 24 literal result keys + 2 fields*4 actions*3 loop keys = 48, cap64.')
print('Budget reserve at maximum caps',(4+4+12)*r['context']['protocol']['trial_cap_seconds'],'remaining',r['context']['remaining_seconds'])
assert (4+4+12)*r['context']['protocol']['trial_cap_seconds']<r['context']['remaining_seconds']
PY"

